		&\leq \frac{1}{q} \norm{ \ket{\hat{\psi}_g}}^2 + \E_{z} \sum_{b'} \Big(\E_x 1_{b' = g_2(x,z)} \Big) \, \bra{\hat{\psi}_g}  \hat{M}^{(\Point,Z),z}_{b'}  \ket{\hat{\psi}_g}
		\label{eq:qld-g-2}
\end{align}
